To write unit tests for `src/billing.js`, we need to mock both the `pg` pool and the `stripe` client. Since the project uses Node.js native test runner (`node --test`), we will use the built-in `node:test` and `node:assert` modules.

Create a new file `test/billing.test.js`:

```javascript
import { test, describe, beforeEach } from 'node:test';
import assert from 'node:assert';
import { mock } from 'node:test';

// Mock the dependencies before importing the module under test
const mockQuery = mock.fn();
mock.module('../src/db.js', {
  namedExports: {
    pool: { query: mockQuery }
  }
});

// Mock Stripe
const mockPaymentIntentsCreate = mock.fn();
mock.module('stripe', {
  default: class {
    constructor() {
      this.paymentIntents = {
        create: mockPaymentIntentsCreate
      };
    }
  }
});

// Now import the function to test
import { chargeInvoice } from '../src/billing.js';

describe('billing.js', () => {
  beforeEach(() => {
    mockQuery.mock.resetCalls();
    mockPaymentIntentsCreate.mock.resetCalls();
  });

  test('chargeInvoice successfully charges and updates the database', async () => {
    const invoiceId = 'inv_123';

    // 1. Mock DB response for invoice lookup
    mockQuery.mock.mockImplementationOnce(async (sql, params) => {
      if (sql.includes('select')) {
        return {
          rows: [{ amount_cents: 1000, currency: 'usd', customer_id: 'cus_999' }]
        };
      }
      return { rows: [] };
    });

    // 2. Mock Stripe response
    mockPaymentIntentsCreate.mock.mockImplementationOnce(async () => ({
      id: 'pi_stripe_test',
      status: 'succeeded'
    }));

    // 3. Execute
    const result = await chargeInvoice(invoiceId);

    // Assertions
    assert.strictEqual(result.invoiceId, invoiceId);
    assert.strictEqual(result.status, 'succeeded');

    // Verify DB calls
    assert.strictEqual(mockQuery.mock.callCount(), 2);
    const [selectCall, updateCall] = mockQuery.mock.calls;

    assert.match(selectCall.arguments[0], /select.*from invoices/);
    assert.deepStrictEqual(selectCall.arguments[1], [invoiceId]);

    assert.match(updateCall.arguments[0], /update invoices set stripe_intent_id/);
    assert.deepStrictEqual(updateCall.arguments[1], ['pi_stripe_test', invoiceId]);

    // Verify Stripe call
    assert.strictEqual(mockPaymentIntentsCreate.mock.callCount(), 1);
    const stripeArgs = mockPaymentIntentsCreate.mock.calls[0].arguments[0];
    assert.strictEqual(stripeArgs.amount, 1000);
    assert.strictEqual(stripeArgs.customer, 'cus_999');
  });

  test('chargeInvoice throws error if invoice is not found', async () => {
    mockQuery.mock.mockImplementationOnce(async () => ({ rows: [] }));

    await assert.rejects(
      () => chargeInvoice('non-existent'),
      { message: 'no such invoice non-existent' }
    );

    assert.strictEqual(mockPaymentIntentsCreate.mock.callCount(), 0);
  });

  test('chargeInvoice fails if Stripe call fails', async () => {
    mockQuery.mock.mockImplementationOnce(async () => ({
      rows: [{ amount_cents: 500, currency: 'usd', customer_id: 'cus_1' }]
    }));

    mockPaymentIntentsCreate.mock.mockImplementationOnce(async () => {
      throw new Error('Stripe API Error');
    });

    await assert.rejects(
      () => chargeInvoice('inv_fail'),
      { message: 'Stripe API Error' }
    );

    // Verify DB update was never called because Stripe failed
    assert.strictEqual(mockQuery.mock.callCount(), 1);
  });
});
```

### Key points for this implementation:
1.  **`node:test` Mocking**: We use `mock.module` to intercept the `pg` pool and the `stripe` constructor. This prevents actual network calls or database connections during tests.
2.  **Dependency Injection**: Since `src/billing.js` imports `pool` directly, we mock the module export.
3.  **Validation**: We verify both the happy path (successful charge and DB update) and edge cases (missing invoice, Stripe failure).
4.  **Running the tests**: You can run this using the existing script: `npm test`.
